}

# RDS PostgreSQL
resource "aws_db_subnet_group" "postgres" {
  name       = "${var.environment}-postgres-subnet"
  subnet_ids = var.vpc_subnet_ids

  tags = var.tags
}

resource "aws_rds_cluster" "postgres" {
  cluster_identifier      = "${var.environment}-postgres"
  engine                  = "aurora-postgresql"
  engine_version          = "15.3"
  database_name           = "appdb"
  master_username         = "postgres"
  master_password         = random_password.db_password.result
  db_subnet_group_name    = aws_db_subnet_group.postgres.name
  db_cluster_parameter_group_name = aws_rds_cluster_parameter_group.postgres.name

  backup_retention_period      = 7
  preferred_backup_window      = "03:00-04:00"
  preferred_maintenance_window = "sun:04:00-sun:05:00"
  skip_final_snapshot          = false
  final_snapshot_identifier    = "${var.environment}-postgres-final-snapshot-${formatdate("YYYY-MM-DD-hhmm", timestamp())}"
  deletion_protection          = var.environment == "prod" ? true : false
  storage_encrypted            = true
  kms_key_id                   = aws_kms_key.rds[0].arn

  vpc_security_group_ids = [aws_security_group.rds.id]

  tags = var.tags
}

resource "aws_rds_cluster_instance" "postgres" {
  cluster_identifier = aws_rds_cluster.postgres.id
  instance_class     = var.rds_instance_class
  engine              = aws_rds_cluster.postgres.engine
  engine_version      = aws_rds_cluster.postgres.engine_version

  publicly_accessible = false

  tags = var.tags
}

resource "aws_rds_cluster_parameter_group" "postgres" {
  family = "aurora-postgresql15"
  name   = "${var.environment}-postgres-params"

  tags = var.tags
}

resource "random_password" "db_password" {
  length  = 32
  special = true
}

resource "aws_secretsmanager_secret" "db_password" {
  name                    = "${var.environment}/rds/master-password"
  recovery_window_in_days = 7

  tags = var.tags
}

resource "aws_secretsmanager_secret_version" "db_password" {
  secret_id = aws_secretsmanager_secret.db_password.id
  secret_string = jsonencode({
    username = "postgres"
    password = random_password.db_password.result
    host     = aws_rds_cluster.postgres.endpoint
    port     = 5432
    dbname   = "appdb"
  })
}

resource "aws_kms_key" "rds" {
  count                   = var.environment == "prod" ? 1 : 0
  description             = "${var.environment} RDS encryption key"
  deletion_window_in_days = 10
  enable_key_rotation     = true

  tags = var.tags
}

resource "aws_security_group" "rds" {
  name   = "${var.environment}-rds-sg"
  vpc_id = data.aws_vpc.default.id

  ingress {
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.eks.id]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = var.tags
}

# IAM Service Account User
resource "aws_iam_user" "service_account" {
  name = "${var.environment}-service-account"

  tags = var.tags
}

resource "aws_iam_role" "service_account" {
  name = "${var.environment}-service-account-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRole"
      Effect = "Allow"
      Principal = {
        AWS = aws_iam_user.service_account.arn
      }
    }]
  })

  tags = var.tags
}

