        Resource = aws_secretsmanager_secret.db_password.arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "service_account" {
  role       = aws_iam_role.service_account.name
  policy_arn = aws_iam_policy.service_account.arn
}

# CloudFront Distribution (prod only)
resource "aws_cloudfront_distribution" "app" {
  count = var.https_distribution_enabled ? 1 : 0

  origin {
    domain_name = aws_s3_bucket.app_assets.bucket_regional_domain_name
    origin_id   = "s3"

